#!/bin/bash
# ============================================================
#  Zanchin Hub Helper - installer for Mac (generated by mac-helper/build-installer.sh)
#  Easiest: paste this one line into Terminal and press Enter, then follow the pop-up boxes:
#     curl -fsSL https://zanchin-booking.netlify.app/zanchin-helper-install.sh | bash
#  It also works as a saved file:  bash zanchin-helper-install.sh
# ============================================================

# If the hub address is ever different, change it on the next line (between the quotes).
HUB_URL="https://zanchin-booking.netlify.app"

TITLE="Zanchin Hub Helper"
SUPPORT="$HOME/Library/Application Support/Zanchin Hub Helper"
LABEL="ca.zanchin.hub-helper"
PLIST="$HOME/Library/LaunchAgents/$LABEL.plist"
LOG="$HOME/Library/Logs/Zanchin Hub Helper.log"
SETUPLOG="$HOME/Library/Logs/Zanchin Hub Helper setup.log"
VOLUMES_DIR="/Volumes"

mkdir -p "$HOME/Library/Logs"
exec > >(tee -a "$SETUPLOG") 2>&1
echo "---- setup run $(date) ----"

say() {  # say "message" -> pop-up box with an OK button
  local msg="${1//\"/\'}"
  osascript -e "display dialog \"$msg\" buttons {\"OK\"} default button 1 with title \"$TITLE\"" >/dev/null 2>&1 || true
}
fail() {
  say "$1

Please take a photo or screenshot of this box and send it to Stan."
  exit 1
}

# 1. Python 3 (comes with Apple's free developer tools)
PY="$(command -v python3 || true)"
if [ -z "$PY" ] || ! "$PY" -c 'import sys; assert sys.version_info >= (3, 8)' 2>/dev/null; then
  xcode-select --install >/dev/null 2>&1 || true
  say "This Mac needs Apple's free developer tools first. A window should have opened: click Install and wait until it finishes (5 to 15 minutes). Then double-click this installer again."
  exit 1
fi

# 2. The token. If this Mac already has one saved, offer to keep it (a pop-up box, not Terminal).
CONFIG="$SUPPORT/config.json"
TOKEN=""
EXISTING_TOKEN=""
if [ -f "$CONFIG" ]; then
  EXISTING_TOKEN="$("$PY" -I -c 'import json, sys
try:
    print(json.load(open(sys.argv[1])).get("token", ""))
except Exception:
    pass' "$CONFIG" 2>/dev/null || true)"
fi
if [ -n "$EXISTING_TOKEN" ]; then
  CHOICE="$(osascript -e 'button returned of (display dialog "This Mac already has a saved token. Keep it and just update the helper?" buttons {"Enter a new token", "Keep it"} default button "Keep it" with title "Zanchin Hub Helper")' 2>/dev/null)" || exit 0
  [ "$CHOICE" = "Keep it" ] && TOKEN="$EXISTING_TOKEN"
fi
if [ -z "$TOKEN" ]; then
  TOKEN="$(osascript -e 'text returned of (display dialog "Paste the token that Stan sent you, then click OK." default answer "" with title "Zanchin Hub Helper" buttons {"Cancel", "OK"} default button "OK")' 2>/dev/null)" || exit 0
  TOKEN="$(printf '%s' "$TOKEN" | tr -d '[:space:]')"
fi
[ -n "$TOKEN" ] || fail "No token was entered. Double-click the installer and try again."

# 3. Put the helper in place
mkdir -p "$SUPPORT" "$HOME/Library/LaunchAgents" || fail "Could not create the helper folder."

cat > "$SUPPORT/zanchin_helper.py" <<'ZH_EOF'
#!/usr/bin/env python3
"""Zanchin Hub helper: builds the local project folders on this Mac's drive.

Runs quietly in the background. About once a minute it asks the hub whether any project is
waiting for THIS machine; for each one it creates the same folders the old Project Ops app
made on Zanchin 12, copies the Lightroom template, and tells the hub it's done. If the drive
isn't connected it just waits and tries again. It only ever creates folders: it never
overwrites or deletes anything.

Only the Python 3 standard library is used (nothing to install).

Config: ~/Library/Application Support/Zanchin Hub Helper/config.json
  {"hub_url": "https://...", "token": "<this machine's token>"}
  optional: "volumes_dir" ("/Volumes"), "volume_name_glob" ("Zanchin 12*"),
            "marker" ("0000_DO_NOT_TOUCH"), "poll_seconds" (600)

Run once and exit:  python3 zanchin_helper.py --once
Check this Mac:      python3 zanchin_helper.py --selftest
"""
import glob
import json
import os
import re
import shutil
import ssl
import sys
import time
import urllib.error
import urllib.request

SUPPORT_DIR = os.path.expanduser("~/Library/Application Support/Zanchin Hub Helper")
CONFIG_PATH = os.environ.get("ZANCHIN_HELPER_CONFIG") or os.path.join(SUPPORT_DIR, "config.json")
LOG_PATH = os.environ.get("ZANCHIN_HELPER_LOG") or os.path.expanduser("~/Library/Logs/Zanchin Hub Helper.log")
STATUS_PATH = os.path.join(os.path.dirname(CONFIG_PATH), "status.json")        # read by the menu bar app
TRIGGER_PATH = os.path.join(os.path.dirname(CONFIG_PATH), "check-now")         # the menu bar app creates this for "Check now"

DEFAULTS = {
    "hub_url": "",
    "token": "",
    "volumes_dir": "/Volumes",
    "volume_name_glob": "Zanchin 12*",
    "marker": "0000_DO_NOT_TOUCH",      # system folder that proves it's the right drive
    "poll_seconds": 600,                # asks the hub every 10 minutes; "Check now" or plugging in a drive checks at once
}
HEARTBEAT_SECONDS = 30                  # local only (no network): tells the menu bar app the helper is alive
LR_TEMPLATE_BASE = "Zanchin LR Template"
LOCAL_FOLDERS = ["01 Project File", "02 Footage", "03 Audio", "04 GPX", os.path.join("05 Stills", "RAW")]
DELIVERY_FOLDERS = ["Photo Exports", "Project File", "RAW Files", "Video Exports"]
FOLDER_NAME = re.compile(r"\d{4}_[^/\\\x00]+_zanchin")   # e.g. 0712_Woodbridge Nissan_Sales Video_2026-10-22_zanchin


def log(msg):
    line = "{}  {}".format(time.strftime("%Y-%m-%d %H:%M:%S"), msg)
    print(line, flush=True)
    try:
        os.makedirs(os.path.dirname(LOG_PATH), exist_ok=True)
        with open(LOG_PATH, "a", encoding="utf-8") as f:
            f.write(line + "\n")
    except OSError:
        pass


_status = {"state": "starting", "message": "Starting…", "checked_at": 0, "pending": 0, "last_number": None, "last_at": None}


def set_status(state, message, **extra):
    """Writes what the menu bar app shows: state is ok | drive_offline | hub_unreachable | auth_error | error."""
    _status.update(extra)
    now = time.time()
    _status.update({"state": state, "message": message, "checked_at": now, "heartbeat_at": now})
    write_status()


def heartbeat():
    """Between checks: says "still alive" without changing what the menu bar shows for the last check."""
    _status["heartbeat_at"] = time.time()
    write_status()


def write_status():
    try:
        tmp = STATUS_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(_status, f)
        os.replace(tmp, STATUS_PATH)
    except OSError:
        pass


def load_config():
    cfg = dict(DEFAULTS)
    with open(CONFIG_PATH, encoding="utf-8") as f:
        cfg.update(json.load(f))
    if not cfg["hub_url"] or not cfg["token"]:
        raise SystemExit("config.json needs hub_url and token")
    cfg["hub_url"] = cfg["hub_url"].rstrip("/")
    return cfg


def find_drive_root(cfg):
    """The drive is recognised by its marker folder, so a remount as "Zanchin 12-1" (or any
    other name) is still found. Name matches are tried first."""
    vdir = cfg["volumes_dir"]
    candidates = sorted(glob.glob(os.path.join(vdir, cfg["volume_name_glob"])))
    try:
        for name in sorted(os.listdir(vdir)):
            path = os.path.join(vdir, name)
            if path not in candidates:
                candidates.append(path)
    except OSError:
        pass
    for path in candidates:
        try:
            if os.path.isdir(os.path.join(path, cfg["marker"])):
                return path
        except OSError:
            continue    # stale mount
    return None


def volume_names(cfg):
    """Names of everything mounted under /Volumes (one cheap directory listing, no network)."""
    try:
        return set(os.listdir(cfg["volumes_dir"]))
    except OSError:
        return set()


def ssl_context():
    """python.org builds of Python on macOS ship without a certificate list, so use the one macOS
    itself provides when it exists; otherwise fall back to Python's own."""
    system_bundle = "/etc/ssl/cert.pem"
    if os.path.exists(system_bundle):
        return ssl.create_default_context(cafile=system_bundle)
    return ssl.create_default_context()


def api(cfg, payload):
    req = urllib.request.Request(
        cfg["hub_url"] + "/.netlify/functions/ops-helper",
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json", "Authorization": "Bearer " + cfg["token"]},
        method="POST",
    )
    with urllib.request.urlopen(req, timeout=20, context=ssl_context()) as resp:
        return json.loads(resp.read().decode("utf-8"))


def copy_missing(src, dst):
    """Copy a file or folder, leaving anything that already exists untouched."""
    if os.path.isdir(src):
        os.makedirs(dst, exist_ok=True)
        for name in os.listdir(src):
            copy_missing(os.path.join(src, name), os.path.join(dst, name))
    elif not os.path.exists(dst):
        shutil.copy2(src, dst)


def copy_lightroom_template(cfg, root, stills_dir, base_name):
    template_dir = os.path.join(root, cfg["marker"], "Lightroom Template", LR_TEMPLATE_BASE)
    if not os.path.isdir(template_dir):
        return False
    items = os.listdir(template_dir)
    for item in items:
        new_name = item.replace(LR_TEMPLATE_BASE, base_name, 1) if item.startswith(LR_TEMPLATE_BASE) else item
        copy_missing(os.path.join(template_dir, item), os.path.join(stills_dir, new_name))
    return bool(items)


def build_project(cfg, root, folder):
    """Same layout as the old app. Returns (project_path, lightroom_ok)."""
    if not FOLDER_NAME.fullmatch(folder) or folder in (".", ".."):
        raise ValueError("invalid folder name")
    real_root = os.path.realpath(root)
    project = os.path.realpath(os.path.join(root, folder))
    if os.path.dirname(project) != real_root:
        raise ValueError("folder is outside the drive")
    for sub in LOCAL_FOLDERS:
        os.makedirs(os.path.join(project, sub), exist_ok=True)
    for sub in DELIVERY_FOLDERS:
        os.makedirs(os.path.join(project, folder, sub), exist_ok=True)
    lr_ok = copy_lightroom_template(cfg, root, os.path.join(project, "05 Stills"), folder)
    return project, lr_ok


def run_once(cfg):
    root = find_drive_root(cfg)
    if root is None:
        log("Drive not connected (marker folder {} not found); will keep waiting.".format(cfg["marker"]))
        set_status("drive_offline", "Zanchin 12 is not connected")
        return
    pending = api(cfg, {"action": "pending"}).get("pending", [])
    failed = 0
    for item in pending:
        number, folder = str(item.get("number")), str(item.get("folder"))
        try:
            path, lr_ok = build_project(cfg, root, folder)
        except Exception as e:      # never crash the loop over one project
            log("{}: could not build ({})".format(number, e))
            api(cfg, {"action": "failed", "number": number, "error": str(e)})
            failed += 1
            continue
        log("{}: created {}{}".format(number, path, "" if lr_ok else "  (Lightroom template not found)"))
        api(cfg, {"action": "done", "number": number, "path": path, "lightroom": lr_ok})
        _status.update({"last_number": number, "last_at": time.time()})
    if failed:
        set_status("error", "{} project(s) could not be built; see the log".format(failed), pending=failed)
    else:
        set_status("ok", "Running. Nothing waiting.", pending=0)


def selftest():
    """Checks this Mac end to end without creating a real project. Run:  python3 zanchin_helper.py --selftest"""
    ok = True

    def line(passed, text):
        nonlocal ok
        ok = ok and passed
        print("  [{}] {}".format("OK" if passed else "PROBLEM", text))

    print("Zanchin Hub helper self-check\n")
    try:
        cfg = load_config()
        line(True, "Config found, hub is {}".format(cfg["hub_url"]))
    except (OSError, ValueError, SystemExit) as e:
        line(False, "Config problem at {} ({})".format(CONFIG_PATH, e))
        return False
    try:
        res = api(cfg, {"action": "pending"})
        n = len(res.get("pending", []))
        line(True, "Hub accepted this Mac as '{}' ({} project(s) waiting for it)".format(res.get("machine"), n))
    except urllib.error.HTTPError as e:
        line(False, "Hub refused this Mac (HTTP {}). {}".format(e.code, "The token is wrong or not on the hub yet." if e.code == 401 else ""))
    except Exception as e:
        line(False, "Can't reach the hub: {}".format(e))
    root = find_drive_root(cfg)
    if root is None:
        line(False, "Drive not found (no volume with a {} folder). Is it connected?".format(cfg["marker"]))
    else:
        line(True, "Drive found: {}".format(root))
        probe = os.path.join(root, ".zanchin-helper-selftest-{}".format(os.getpid()))
        try:
            os.makedirs(os.path.join(probe, "a"))
            os.rmdir(os.path.join(probe, "a"))
            os.rmdir(probe)
            line(True, "Can create folders on the drive (test folder made and removed)")
        except OSError as e:
            line(False, "Can't write to the drive: {}. macOS may need permission: System Settings > Privacy & Security > Files and Folders / Full Disk Access.".format(e))
        template = os.path.join(root, cfg["marker"], "Lightroom Template", LR_TEMPLATE_BASE)
        if os.path.isdir(template) and os.listdir(template):
            line(True, "Lightroom template found ({} items)".format(len(os.listdir(template))))
        else:
            line(False, "Lightroom template missing at {}".format(template))
    print("\n" + ("ALL GOOD: this Mac will build the folders for projects created in the hub." if ok else "Something needs fixing (see PROBLEM above)."))
    return ok


def main():
    if "--selftest" in sys.argv:
        sys.exit(0 if selftest() else 1)
    cfg = load_config()
    once = "--once" in sys.argv
    log("Helper started ({}).".format("single run" if once else "polling every {}s".format(cfg["poll_seconds"])))
    try:    # remember the last project built across restarts
        with open(STATUS_PATH, encoding="utf-8") as f:
            old = json.load(f)
        _status.update({k: old.get(k) for k in ("last_number", "last_at")})
    except (OSError, ValueError):
        pass
    while True:
        try:
            run_once(cfg)
        except urllib.error.HTTPError as e:
            log("Hub said {} {}".format(e.code, "(check the token)" if e.code == 401 else ""))
            set_status("auth_error" if e.code == 401 else "hub_unreachable",
                       "The hub rejected this Mac's token" if e.code == 401 else "The hub returned an error ({})".format(e.code))
        except Exception as e:
            log("Could not reach the hub: {}".format(e))
            set_status("hub_unreachable", "Can't reach the hub (internet?)")
        if once:
            return
        # wait for the next poll. Wakes early if the menu bar app asks for "Check now", or when a new
        # drive is plugged in, so the slow poll never holds up a project that was waiting for the drive.
        waited = 0
        limit = max(15, int(cfg["poll_seconds"]))
        volumes_before = volume_names(cfg)
        while waited < limit and not os.path.exists(TRIGGER_PATH):
            time.sleep(1)
            waited += 1
            if waited % HEARTBEAT_SECONDS == 0:
                heartbeat()
                if volume_names(cfg) - volumes_before:
                    break
        try:
            os.remove(TRIGGER_PATH)
        except OSError:
            pass


if __name__ == "__main__":
    main()
ZH_EOF

"$PY" - "$SUPPORT/config.json" "$HUB_URL" "$TOKEN" "$VOLUMES_DIR" <<'PYEOF' || fail "Could not save the settings."
import json, os, sys
path, hub, token, vols = sys.argv[1:5]
try:
    with open(path) as f:
        cfg = json.load(f)          # keep anything already set up on this Mac (hub address, drive name, ...)
    if not isinstance(cfg, dict):
        cfg = {}
except Exception:
    cfg = {}
cfg["token"] = token
if not cfg.get("hub_url"):
    cfg["hub_url"] = hub.rstrip("/")
if vols != "/Volumes":
    cfg["volumes_dir"] = vols
try:
    slow_enough = float(cfg.get("poll_seconds", 0)) >= 300
except (TypeError, ValueError):
    slow_enough = False
if not slow_enough:
    cfg["poll_seconds"] = 600       # asks the hub every 10 minutes (was every minute: it used up Netlify credits)
with open(path, "w") as f:
    json.dump(cfg, f, indent=2)
os.chmod(path, 0o600)
PYEOF

cat > "$PLIST" <<PLISTEOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>$LABEL</string>
  <key>ProgramArguments</key><array><string>$PY</string><string>$SUPPORT/zanchin_helper.py</string></array>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>ThrottleInterval</key><integer>30</integer>
  <key>StandardOutPath</key><string>/dev/null</string>
  <key>StandardErrorPath</key><string>$HOME/Library/Logs/Zanchin Hub Helper.errors.log</string>
</dict></plist>
PLISTEOF

# 4. Start it now and at every login
launchctl bootout "gui/$(id -u)/$LABEL" 2>/dev/null || true
launchctl bootstrap "gui/$(id -u)" "$PLIST" || fail "Could not start the helper."
launchctl kickstart -k "gui/$(id -u)/$LABEL" 2>/dev/null || true

# 5. Menu bar icon (optional; skipped if Apple's developer tools are not installed)
cat > "$SUPPORT/ZanchinHelperMenu.swift" <<'ZH_EOF'
// Zanchin Hub Helper: menu bar status icon.
// Shows whether the helper (zanchin_helper.py) is running and healthy, next to the battery and clock.
// It only READS the helper's status file; the helper does the real work. Quitting this icon does not stop the helper.
//
// Build: swiftc -O -swift-version 5 ZanchinHelperMenu.swift -o ZanchinHelperMenu   (install.sh does this)
import Cocoa

let home = NSHomeDirectory()
let supportDir = home + "/Library/Application Support/Zanchin Hub Helper"
let statusPath = supportDir + "/status.json"
let configPath = supportDir + "/config.json"
let triggerPath = supportDir + "/check-now"
let logPath = home + "/Library/Logs/Zanchin Hub Helper.log"
let helperLabel = "ca.zanchin.hub-helper"

func readJSON(_ path: String) -> [String: Any]? {
    guard let data = FileManager.default.contents(atPath: path) else { return nil }
    return (try? JSONSerialization.jsonObject(with: data)) as? [String: Any]
}

func ago(_ t: Double) -> String {
    let s = max(0, Int(Date().timeIntervalSince1970 - t))
    if s < 10 { return "just now" }
    if s < 60 { return "\(s)s ago" }
    if s < 3600 { return "\(s / 60) min ago" }
    if s < 86400 { return "\(s / 3600) h ago" }
    return "\(s / 86400) d ago"
}

enum Level { case good, warn, bad }

final class App: NSObject, NSApplicationDelegate, NSMenuDelegate {
    let item = NSStatusBar.system.statusItem(withLength: NSStatusItem.variableLength)
    let menu = NSMenu()
    var timer: Timer?

    func applicationDidFinishLaunching(_ n: Notification) {
        menu.delegate = self
        item.menu = menu
        refresh()
        timer = Timer.scheduledTimer(withTimeInterval: 5, repeats: true) { [weak self] _ in self?.refresh() }
    }

    func menuWillOpen(_ menu: NSMenu) { refresh() }

    func current() -> (Level, String, [String: Any]) {
        guard let st = readJSON(statusPath) else { return (.bad, "Helper has not started yet", [:]) }
        // newer helpers write "heartbeat_at" every 30s even between hub checks; older ones only "checked_at"
        let beat = st["heartbeat_at"] as? Double
        let alive = beat ?? (st["checked_at"] as? Double ?? 0)
        let poll = (readJSON(configPath)?["poll_seconds"] as? Double) ?? 600
        let limit = beat != nil ? 180.0 : max(180, poll * 3)
        if Date().timeIntervalSince1970 - alive > limit { return (.bad, "Helper is not running", st) }
        let msg = st["message"] as? String ?? ""
        switch st["state"] as? String ?? "" {
        case "ok": return (.good, msg.isEmpty ? "Running" : msg, st)
        case "drive_offline", "hub_unreachable": return (.warn, msg, st)
        default: return (.bad, msg.isEmpty ? "Something is wrong" : msg, st)
        }
    }

    func color(_ l: Level) -> NSColor { l == .good ? .systemGreen : (l == .warn ? .systemOrange : .systemRed) }

    func line(_ title: String, dot: NSColor? = nil) -> NSMenuItem {
        let mi = NSMenuItem(title: title, action: nil, keyEquivalent: "")
        mi.isEnabled = false
        if let dot = dot {
            let s = NSMutableAttributedString(string: "● ", attributes: [.foregroundColor: dot])
            s.append(NSAttributedString(string: title, attributes: [.foregroundColor: NSColor.labelColor]))
            mi.attributedTitle = s
        }
        return mi
    }

    func action(_ title: String, _ sel: Selector) -> NSMenuItem {
        let mi = NSMenuItem(title: title, action: sel, keyEquivalent: "")
        mi.target = self
        return mi
    }

    func refresh() {
        let (level, message, st) = current()
        if let b = item.button {
            let img = NSImage(systemSymbolName: "externaldrive.fill", accessibilityDescription: "Zanchin Hub Helper")
            img?.isTemplate = true
            b.image = img
            b.imagePosition = .imageLeft
            b.attributedTitle = NSAttributedString(string: " ●", attributes: [.foregroundColor: color(level), .font: NSFont.systemFont(ofSize: 11)])
            b.toolTip = "Zanchin Hub Helper: " + message
        }
        menu.removeAllItems()
        menu.addItem(line("Zanchin Hub Helper"))
        menu.addItem(line(message, dot: color(level)))
        if let t = st["checked_at"] as? Double, t > 0 { menu.addItem(line("Last check: " + ago(t))) }
        if let n = st["last_number"] as? String, let t = st["last_at"] as? Double {
            menu.addItem(line("Last project built: \(n) · " + ago(t)))
        }
        menu.addItem(.separator())
        menu.addItem(action("Check now", #selector(checkNow)))
        menu.addItem(action("Open Zanchin Hub", #selector(openHub)))
        menu.addItem(action("Show log", #selector(showLog)))
        menu.addItem(action("Restart helper", #selector(restartHelper)))
        menu.addItem(.separator())
        menu.addItem(action("Quit this icon (helper keeps running)", #selector(quit)))
    }

    @objc func checkNow() {
        FileManager.default.createFile(atPath: triggerPath, contents: Data())
        DispatchQueue.main.asyncAfter(deadline: .now() + 3) { [weak self] in self?.refresh() }
    }

    @objc func openHub() {
        let url = (readJSON(configPath)?["hub_url"] as? String) ?? ""
        if let u = URL(string: url + "/ops"), !url.isEmpty { NSWorkspace.shared.open(u) }
    }

    @objc func showLog() { NSWorkspace.shared.open(URL(fileURLWithPath: logPath)) }

    @objc func restartHelper() {
        let p = Process()
        p.executableURL = URL(fileURLWithPath: "/bin/launchctl")
        p.arguments = ["kickstart", "-k", "gui/\(getuid())/\(helperLabel)"]
        try? p.run()
        DispatchQueue.main.asyncAfter(deadline: .now() + 4) { [weak self] in self?.refresh() }
    }

    @objc func quit() { NSApp.terminate(nil) }
}

let app = NSApplication.shared
app.setActivationPolicy(.accessory)   // menu bar only, no Dock icon
let delegate = App()
app.delegate = delegate
app.run()
ZH_EOF
MENU_LABEL="ca.zanchin.hub-helper-menu"
MENU_PLIST="$HOME/Library/LaunchAgents/$MENU_LABEL.plist"
if xcode-select -p >/dev/null 2>&1 && command -v swiftc >/dev/null 2>&1 \
   && swiftc -O -swift-version 5 "$SUPPORT/ZanchinHelperMenu.swift" -o "$SUPPORT/ZanchinHelperMenu" 2>"$SUPPORT/menu-build.log"; then
  cat > "$MENU_PLIST" <<MENUEOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>$MENU_LABEL</string>
  <key>ProgramArguments</key><array><string>$SUPPORT/ZanchinHelperMenu</string></array>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>ProcessType</key><string>Interactive</string>
</dict></plist>
MENUEOF
  launchctl bootout "gui/$(id -u)/$MENU_LABEL" 2>/dev/null || true
  launchctl bootstrap "gui/$(id -u)" "$MENU_PLIST" 2>/dev/null || true
  launchctl kickstart -k "gui/$(id -u)/$MENU_LABEL" 2>/dev/null || true
fi

# 6. Check everything and tell the user in plain words
sleep 2
CHECK="$("$PY" "$SUPPORT/zanchin_helper.py" --selftest 2>&1 || true)"
echo "$CHECK"
if echo "$CHECK" | grep -q "Can't reach the hub"; then
  say "The helper is installed, but it cannot reach the hub. Check the internet connection. If this keeps happening, the token may be wrong: ask Stan for a new one.

$CHECK"
elif echo "$CHECK" | grep -qi "token\|unauthor\|401"; then
  say "The helper is installed, but the hub did not accept the token. Ask Stan to double-check it.

$CHECK"
elif echo "$CHECK" | grep -q "Drive not found"; then
  say "DONE. The helper is installed and talking to the hub.

One thing left: plug in the Zanchin 12 drive. The helper will build the project folders by itself once it is connected."
elif echo "$CHECK" | grep -q "PROBLEM"; then
  say "The helper is installed, but something still needs fixing:

$CHECK"
else
  say "ALL DONE. The helper is installed and working. It starts by itself every time you log in. You can close this window."
fi
exit 0
